<?php get_header(); $items=new WP_Query(['post_type'=>'gc_event','posts_per_page'=>24,'post_status'=>'publish','orderby'=>'meta_value','meta_key'=>'gc_event_date','order'=>'ASC']); ?>
<main class="gc-interior"><section class="gc-page-hero gc-dark"><div class="gc-container"><span class="gc-kicker">Gather. Learn. Connect.</span><h1>Events that<br><em>move leaders.</em></h1><p>National programmes, chapter gatherings, masterclasses and community sessions.</p></div></section><section class="gc-section"><div class="gc-container"><div class="gc-card-grid"><?php if($items->have_posts()){while($items->have_posts()){$items->the_post(); ?><article class="gc-content-card"><div class="gc-card-body"><small><?php echo esc_html(get_post_meta(get_the_ID(),'gc_event_type',true)?:'Event');?></small><h3><?php the_title();?></h3><p><strong><?php echo esc_html(get_post_meta(get_the_ID(),'gc_event_date',true));?></strong><br><?php echo esc_html(get_post_meta(get_the_ID(),'gc_event_location',true));?></p><a href="<?php the_permalink();?>">View event →</a></div></article><?php } wp_reset_postdata(); } else { ?><div class="gc-empty">Upcoming events will appear here.</div><?php } ?></div></div></section></main><?php get_footer(); ?>
